import {
  intensity,
  channels,
  wavelengthRGB,
  falseRGB,
  isCircular,
  aperture,
  separation,
  airy,
} from "./physics.js";
// Gamma and false-colour lookup tables are visual only; physics stays linear.
const gamma = Uint8ClampedArray.from(
  { length: 65536 },
  (_, i) => 255 * (i / 65535) ** (1 / 2.2),
);
const falseMap = Array.from({ length: 4096 }, (_, i) =>
  falseRGB(i / 4095).map((v) => gamma[Math.round(v * 65535)]),
);
const encoded = (v) => gamma[Math.round(Math.min(1, Math.max(0, v)) * 65535)];
/** Background rasterization; transferable buffers avoid inter-thread copies. */
self.onmessage = ({ data }) => {
  const { id, p, width: w, height: h, components = false } = data,
    start = performance.now();
  const out = Array.from(
    { length: components ? 3 : 1 },
    () => new Uint8ClampedArray(w * h * 4),
  );
  const weights = channels(p),
    rgb = [wavelengthRGB(p.lambda1), wavelengthRGB(p.lambda2)],
    gain = p.exposure / Math.max(1, weights[0] + weights[1]);
  const span = p.span * 1e-3,
    cx = p.cx * 1e-3,
    cy = p.cy * 1e-3,
    sy = (span * h) / w,
    circular = isCircular(p),
    a = aperture(p),
    d = separation(p),
    double = p.mode === "double-hole";
  const maxR = Math.hypot(Math.abs(cx) + span / 2, Math.abs(cy) + sy / 2),
    maxU =
      (Math.PI * a * maxR) /
      Math.hypot(p.screen, maxR) /
      (Math.min(p.lambda1, p.lambda2) * 1e-9);
  const size = Math.min(100000, Math.max(2048, Math.ceil(maxU / 0.001))),
    table = circular
      ? Float64Array.from({ length: size + 1 }, (_, i) =>
          airy((maxU * i) / size),
        )
      : null;
  function circ(x, y, wl) {
    const r = Math.hypot(p.screen, x, y),
      u = (Math.PI * a * Math.hypot(x, y)) / r / wl,
      q = (u / maxU) * size,
      i = Math.min(size - 1, Math.floor(q)),
      f = q - i;
    return (
      (table[i] * (1 - f) + table[i + 1] * f) *
      (double ? Math.cos((Math.PI * d * x) / r / wl) ** 2 : 1)
    );
  }
  const slit = circular
    ? null
    : [p.lambda1, p.lambda2].map((l) =>
        Float64Array.from({ length: w }, (_, i) =>
          intensity(p, cx + ((i + 0.5) / w - 0.5) * span, 0, l),
        ),
      );
  const wl1 = p.lambda1 * 1e-9,
    wl2 = p.lambda2 * 1e-9;
  for (let y = 0; y < (circular ? h : 1); y++) {
    const py = cy + (0.5 - (y + 0.5) / h) * sy;
    for (let x = 0; x < w; x++) {
      const px = cx + ((x + 0.5) / w - 0.5) * span;
      const v0 = weights[0]
          ? (slit ? slit[0][x] : circ(px, py, wl1)) * weights[0]
          : 0,
        v1 = weights[1]
          ? (slit ? slit[1][x] : circ(px, py, wl2)) * weights[1]
          : 0;
      const j = (y * w + x) * 4;
      for (let channel = 0; channel < out.length; channel++) {
        const vA = (channel === 2 ? 0 : v0) * gain,
          vB = (channel === 1 ? 0 : v1) * gain,
          buf = out[channel];
        if (p.palette === "false") {
          const c = falseMap[Math.round(Math.min(1, vA + vB) * 4095)];
          buf[j] = c[0];
          buf[j + 1] = c[1];
          buf[j + 2] = c[2];
        } else {
          buf[j] = encoded(vA * rgb[0][0] + vB * rgb[1][0]);
          buf[j + 1] = encoded(vA * rgb[0][1] + vB * rgb[1][1]);
          buf[j + 2] = encoded(vA * rgb[0][2] + vB * rgb[1][2]);
        }
        buf[j + 3] = 255;
      }
    }
  }
  // Long ideal slits are invariant along y: calculate one row and reuse it.
  if (slit)
    for (const buffer of out) {
      const row = buffer.subarray(0, w * 4);
      for (let y = 1; y < h; y++) buffer.set(row, y * w * 4);
    }
  self.postMessage(
    {
      id,
      width: w,
      height: h,
      buffers: out.map((a) => a.buffer),
      ms: performance.now() - start,
    },
    out.map((a) => a.buffer),
  );
};
