/** Equazioni scalari di Fraunhofer; tutte le grandezze interne in SI.
 * Vedere docs/MODELLI.md per derivazione, fonti e criteri di validita.
 */
export const AIRY_ZERO = 3.8317059702075125;
export const defaults = () => ({
  mode: "double-slit",
  lambda1: 650,
  lambda2: 450,
  power1: 1,
  power2: 1,
  on1: true,
  on2: true,
  dual: false,
  width: 40,
  diameter: 100,
  separationSlit: 250,
  separationHole: 250,
  source: 10,
  screen: 2,
  palette: "spectral",
  exposure: 1,
  autoScale: true,
  span: 20,
  cx: 0,
  cy: 0,
  markers: true,
  quality: 900,
});
export const isCircular = (p) => p.mode.includes("hole");
export const isDouble = (p) => p.mode.startsWith("double");
export const aperture = (p) => (isCircular(p) ? p.diameter : p.width) * 1e-6;
export const separation = (p) =>
  (isCircular(p) ? p.separationHole : p.separationSlit) * 1e-6;
export function sinc(x) {
  return Math.abs(x) < 1e-5 ? 1 - (x * x) / 6 : Math.sin(x) / x;
}
/** J1: rational minimax for |x|<8, asymptotic rational for larger x.
 * Numerical Recipes/Cephes-style coefficients; checked against high-precision NIST series.
 * Finite numerical error is distinct from a physical approximation.
 */
export function j1(x) {
  const a = Math.abs(x);
  let y, ans;
  if (a < 8) {
    y = x * x;
    ans =
      (x *
        (72362614232 +
          y *
            (-7895059235 +
              y *
                (242396853.1 +
                  y * (-2972611.439 + y * (15704.4826 + y * -30.16036606)))))) /
      (144725228442 +
        y *
          (2300535178 +
            y * (18583304.74 + y * (99447.43394 + y * (376.9991397 + y)))));
  } else {
    const z = 8 / a;
    y = z * z;
    const phase = a - 2.356194491;
    const u =
      1 +
      y *
        (0.00183105 +
          y *
            (-0.00003516396496 +
              y * (0.000002457520174 + y * -0.000000240337019)));
    const v =
      0.04687499995 +
      y *
        (-0.0002002690873 +
          y *
            (0.000008449199096 +
              y * (-0.00000088228987 + y * 0.000000105787412)));
    ans =
      Math.sqrt(0.636619772 / a) *
      (Math.cos(phase) * u - z * Math.sin(phase) * v);
    if (x < 0) ans = -ans;
  }
  return ans;
}
export function airy(u) {
  if (Math.abs(u) < 1e-5) return 1 - (u * u) / 4;
  return ((2 * j1(u)) / u) ** 2;
}
/** Peak-normalized pattern: the powers are relative on-axis intensities for
 * each CURRENT aperture geometry. Not absolute W/m² or constant source power.
 * S affects validity of uniform illumination, not this normalized shape.
 */
export function intensity(p, x, y, lambda) {
  const a = aperture(p),
    L = p.screen,
    wl = lambda * 1e-9;
  const r = isCircular(p) ? Math.hypot(L, x, y) : Math.hypot(L, x);
  const sx = x / r;
  const sr = isCircular(p) ? Math.hypot(x, y) / r : Math.abs(sx);
  const env = isCircular(p)
    ? airy((Math.PI * a * sr) / wl)
    : sinc((Math.PI * a * sx) / wl) ** 2;
  return (
    env * (isDouble(p) ? Math.cos((Math.PI * separation(p) * sx) / wl) ** 2 : 1)
  );
}
export function position(s, L) {
  return Math.abs(s) < 1 ? (L * s) / Math.sqrt(1 - s * s) : null;
}
export function firstFeature(p, lambda) {
  const a = aperture(p),
    wl = lambda * 1e-9;
  return position(
    isDouble(p)
      ? wl / separation(p)
      : ((isCircular(p) ? AIRY_ZERO / Math.PI : 1) * wl) / a,
    p.screen,
  );
}
export function firstMinimum(p, lambda) {
  return position(
    ((isCircular(p) ? AIRY_ZERO / Math.PI : 1) * lambda * 1e-9) / aperture(p),
    p.screen,
  );
}
export function channels(p) {
  return [p.on1 ? p.power1 : 0, p.dual && p.on2 ? p.power2 : 0];
}
export function validity(p) {
  const R = (aperture(p) + (isDouble(p) ? separation(p) : 0)) / 2;
  const wavelengths = [
    ...(p.on1 ? [p.lambda1] : []),
    ...(p.dual && p.on2 ? [p.lambda2] : []),
  ];
  const wl =
    Math.min(...(wavelengths.length ? wavelengths : [p.lambda1, p.lambda2])) *
    1e-9;
  const F = ((R * R) / wl) * (1 / p.source + 1 / p.screen);
  const overlap = isDouble(p) && separation(p) <= aperture(p);
  return {
    F,
    valid: F <= 0.1 && !overlap,
    reason: overlap
      ? "Le aperture si sovrappongono: aumenta la separazione."
      : F > 0.1
        ? "Campo lontano non soddisfatto: aumenta S e L o riduci le aperture. Serve un modello di Fresnel."
        : "",
  };
}
export function automaticSpan(p, aspect = 1) {
  const ls = [
    ...(p.on1 ? [p.lambda1] : []),
    ...(p.dual && p.on2 ? [p.lambda2] : []),
  ];
  const radii = (ls.length ? ls : [p.lambda1])
    .map((l) => firstMinimum(p, l))
    .filter(Number.isFinite);
  return Math.min(
    2000,
    Math.max(
      0.02,
      (radii.length
        ? Math.max(...radii) *
          (isCircular(p) ? 4.2 / Math.max(0.15, aspect) : 2.8)
        : 0.02) * 1000,
    ),
  );
}
export function profile(p, n = 4097) {
  const x = new Float64Array(n),
    a = new Float64Array(n),
    b = new Float64Array(n),
    sum = new Float64Array(n);
  const powers = channels(p);
  for (let i = 0; i < n; i++) {
    x[i] = (p.cx + (i / (n - 1) - 0.5) * p.span) * 1e-3;
    a[i] = powers[0] * intensity(p, x[i], 0, p.lambda1);
    b[i] = powers[1] * intensity(p, x[i], 0, p.lambda2);
    sum[i] = a[i] + b[i];
  }
  return { x, a, b, sum };
}
export function wavelengthRGB(n) {
  let r = 0,
    g = 0,
    b = 0;
  if (n < 440) {
    r = (440 - n) / 60;
    b = 1;
  } else if (n < 490) {
    g = (n - 440) / 50;
    b = 1;
  } else if (n < 510) {
    g = 1;
    b = (510 - n) / 20;
  } else if (n < 580) {
    r = (n - 510) / 70;
    g = 1;
  } else if (n < 645) {
    r = 1;
    g = (645 - n) / 65;
  } else r = 1;
  const f =
    n < 420
      ? 0.3 + (0.7 * (n - 380)) / 40
      : n > 700
        ? 0.3 + (0.7 * (780 - n)) / 80
        : 1;
  return [r, g, b].map((v) => Math.max(0, v * f));
}
export function falseRGB(t) {
  const stops = [
    [0, 0, 0],
    [0.12, 0.04, 0.32],
    [0.25, 0.15, 0.65],
    [0.1, 0.65, 0.8],
    [0.8, 0.9, 0.3],
    [1, 0.97, 0.85],
  ];
  const q = Math.max(0, Math.min(1, t)) * (stops.length - 1),
    i = Math.min(stops.length - 2, Math.floor(q)),
    f = q - i;
  return stops[i].map((v, k) => v + (stops[i + 1][k] - v) * f);
}
